package com.chondrimaishrat.elearning.quiz;
import com.chondrimaishrat.elearning.course.*; import com.chondrimaishrat.elearning.enrollment.EnrollmentRepository; import com.chondrimaishrat.elearning.user.UserAccount; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class QuizService {private final QuizQuestionRepository questions;private final QuizAttemptRepository attempts;private final CourseRepository courses;private final EnrollmentRepository enrollments;public QuizService(QuizQuestionRepository q,QuizAttemptRepository a,CourseRepository c,EnrollmentRepository e){questions=q;attempts=a;courses=c;enrollments=e;}public List<QuizQuestion> questions(Long id){return questions.findByCourseIdOrderByIdAsc(id);}@Transactional public void add(UserAccount instructor,Long courseId,QuestionForm f){Course c=courses.findById(courseId).orElseThrow(()->new IllegalArgumentException("Course not found."));if(!c.getInstructor().getId().equals(instructor.getId()))throw new IllegalArgumentException("You can only edit your own course.");questions.save(new QuizQuestion(c,f.getQuestionText(),f.getOptionA(),f.getOptionB(),f.getOptionC(),f.getOptionD(),f.getCorrectOption()));}@Transactional public QuizAttempt submit(UserAccount student,Long courseId,Map<String,String> answers){if(!enrollments.existsByStudentIdAndCourseId(student.getId(),courseId))throw new IllegalArgumentException("Enroll before taking this quiz.");List<QuizQuestion> list=questions(courseId);if(list.isEmpty())throw new IllegalArgumentException("This course has no quiz questions yet.");int score=0;for(QuizQuestion q:list)if(q.getCorrectOption().equals(answers.get("question_"+q.getId())))score++;return attempts.save(new QuizAttempt(student,courses.findById(courseId).orElseThrow(),score,list.size()));}}
